using System;using System.IO;using System.Reflection;using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad]public static class CompactInputAuditV08 {
  const string Key="ZTM_COMPACT_INPUT_V08";static GameView view;static RenderTexture rt;static int phase,size,warm,checks;static float at;static double start;static Store store;static Button retired;static StringBuilder log=new StringBuilder();static readonly int[] Widths={360,360,480},Heights={640,800,960};
  static string Root=>Directory.GetParent(Application.dataPath).FullName;static VisualElement UI=>view.GetComponent<UIDocument>().rootVisualElement;
  static CompactInputAuditV08(){EditorApplication.update+=Tick;}
  public static void BatchStart(){Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",Path.Combine(Root,".tooling","v08-compact-input-1","save"));UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetBool(Key,true);EditorApplication.EnterPlaymode();}
  static void Check(bool ok,string label){if(!ok)throw new Exception(label);checks++;log.AppendLine("PASS "+label);}
  static void At(int next){phase=next;warm=0;at=Time.unscaledTime;}
  static bool Warm()=>++warm>18&&Time.unscaledTime-at>.3f;
  static string Focus=>(UI.panel.focusController.focusedElement as VisualElement)?.name??"none";
  sealed class Store:IStateStore{public PlayerState state;public bool fail;public int writes,attempts;public PlayerState Load(out string notice){notice="";return new GameModel(state).Snapshot;}public bool Save(PlayerState next,out string error){attempts++;error=fail?"Save failed: IOException":"";if(fail)return false;state=new GameModel(next).Snapshot;writes++;return true;}}
  static PlayerState Fixture(int cash=1000,int parts=0){var s=new PlayerState{cash=cash,freeSpins=0};s.fragments[0]=parts;s.tutorial.completed=true;s.tutorial.storySeenMask=15;return s;}
  static void Set(PlayerState state,bool controlled=false){view.SetQaState(state,0);if(controlled){store=new Store{state=view.Model.Snapshot};typeof(GameView).GetField("session",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(view,new GameSession(store,new SeededRandom(57)));}}
  static void Submit(Button b){using(var e=NavigationSubmitEvent.GetPooled()){e.target=b;b.SendEvent(e);}}
  static void SendKey(KeyCode key,bool down){var target=(UI.panel.focusController.focusedElement as VisualElement)??UI;if(down){using(var e=KeyDownEvent.GetPooled(new Event{type=EventType.KeyDown,keyCode=key})){e.target=target;target.SendEvent(e);}}else{using(var e=KeyUpEvent.GetPooled(new Event{type=EventType.KeyUp,keyCode=key})){e.target=target;target.SendEvent(e);}}}
  static void Tab(){var target=(UI.panel.focusController.focusedElement as VisualElement)??UI;SendKey(KeyCode.Tab,true);using(var e=NavigationMoveEvent.GetPooled(NavigationMoveEvent.Direction.Next,EventModifiers.None)){e.target=target;target.SendEvent(e);}}
  static void Tap(Button b){var p=b.worldBound.center;var hit=UI.panel.Pick(p);Check(hit==b||b.Contains(hit),"actual panel pick "+b.name);using(var e=PointerDownEvent.GetPooled(new Event{type=EventType.MouseDown,button=0,mousePosition=p})){e.target=hit;hit.SendEvent(e);}using(var e=PointerUpEvent.GetPooled(new Event{type=EventType.MouseUp,button=0,mousePosition=p})){e.target=b;b.SendEvent(e);}}
  static void Targets(){foreach(var b in UI.Query<Button>().ToList()){if(!UiInputCoordinator.CanActivate(b))continue;var r=b.worldBound;Check(r.width>=43.9f&&r.height>=43.9f,"44-unit target "+b.name);foreach(var p in new[]{r.center,new Vector2(r.xMin+1,r.yMin+1),new Vector2(r.xMax-1,r.yMin+1),new Vector2(r.xMin+1,r.yMax-1),new Vector2(r.xMax-1,r.yMax-1)}){var hit=UI.panel.Pick(p);Check(hit==b||b.Contains(hit),"edge/centre hit "+b.name);}var l=b.Q<Label>("button-caption");Check(l==null||l.pickingMode==PickingMode.Ignore,"caption does not intercept "+b.name);}}
  static void Tick(){if(!SessionState.GetBool(Key,false)||!EditorApplication.isPlaying)return;try{if(start==0)start=EditorApplication.timeSinceStartup;if(EditorApplication.timeSinceStartup-start>120)throw new Exception("bounded compact audit timeout");if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null)return;}
   if(phase==0){rt=new RenderTexture(Widths[size],Heights[size],0,RenderTextureFormat.ARGB32);rt.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=rt;Set(Fixture(59,20));At(1);}
   else if(phase==1&&Warm()){Targets();Check(!UI.Q<Button>("buy-0").enabledInHierarchy,"coins gate");view.QaBuy(0);Check(view.Model.PurchasedCount==0&&view.Model.Snapshot.cash==59,"direct purchase cannot bypass coins");Set(Fixture(60,19));At(2);}
   else if(phase==2&&Warm()){Check(!UI.Q<Button>("buy-0").enabledInHierarchy,"parts gate");view.QaBuy(0);Check(view.Model.PurchasedCount==0&&view.Model.Snapshot.fragments[0]==19,"direct purchase cannot bypass parts");view.QaClick("menu");At(3);}
   else if(phase==3&&Warm()){Targets();Check(Focus=="tutorial-replay","menu initial focus");Tab();Check(Focus=="motion-toggle","paired Tab advances once");int spins=view.Model.Snapshot.spins;Submit(UI.Q<Button>("spin"));Check(view.Model.Snapshot.spins==spins,"modal blocks underlying submit");view.QaClick("close-settings");At(4);}
   else if(phase==4&&Warm()){Check(Focus=="menu","modal restores trigger");view.QaClick("menu");At(5);}
   else if(phase==5&&Warm()){view.QaClick("tutorial-replay");At(6);}
   else if(phase==6&&Warm()){Check(Focus=="tutorial-next","replay initial focus");Targets();Tab();Check(Focus=="tutorial-skip","replay paired Tab advances once");SendKey(KeyCode.Space,true);Submit(UI.Q<Button>("tutorial-skip"));SendKey(KeyCode.Space,false);At(7);}
   else if(phase==7&&Warm()){Check(Focus=="menu","replay dismissal restores trigger");view.GetComponent<UIDocument>().panelSettings.targetTexture=null;rt.Release();UnityEngine.Object.Destroy(rt);rt=null;if(++size<3){At(0);return;}size=0;rt=new RenderTexture(360,640,0,RenderTextureFormat.ARGB32);rt.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=rt;Set(Fixture(),true);At(8);}
   else if(phase==8&&Warm()){var b=UI.Q<Button>("spin");b.Focus();SendKey(KeyCode.Space,true);Submit(b);for(int i=0;i<30;i++)Submit(b);Check(view.Model.Snapshot.spins==1&&store.writes==1,"held submit commits one spin before cosmetics");At(9);}
   else if(phase==9&&!view.QaSpinning){for(int i=0;i<30;i++)Submit(UI.Q<Button>("spin"));Check(view.Model.Snapshot.spins==1&&store.writes==1,"held submit remains consumed after presentation");At(10);}
   else if(phase==10&&Warm()){SendKey(KeyCode.Space,false);SendKey(KeyCode.Space,true);Submit(UI.Q<Button>("spin"));SendKey(KeyCode.Space,false);Check(view.Model.Snapshot.spins==2&&store.writes==2,"new key after existing cooldown commits once");At(11);}
   else if(phase==11&&!view.QaSpinning){Set(Fixture(60,20),true);store.fail=true;At(12);}
   else if(phase==12&&Warm()){var b=UI.Q<Button>("buy-0");b.Focus();SendKey(KeyCode.Return,true);Submit(b);for(int i=0;i<30;i++)Submit(b);SendKey(KeyCode.Return,false);Check(store.attempts==1&&store.writes==0,"held purchase failure writes once");Check(view.Model.Snapshot.cash==60&&view.Model.PurchasedCount==0,"failed purchase rolls back resources");view.QaClick("menu");At(13);}
   else if(phase==13&&Warm()){Check(UI.Q<Label>("save-status").text.Contains("Could not save"),"truthful English rejected-write status");view.QaClick("close-settings");store.fail=false;At(14);}
   else if(phase==14&&Warm()){retired=UI.Q<Button>("buy-0");Tap(retired);for(int i=0;i<30;i++){Submit(retired);view.QaBuy(0);}Check(store.writes==1&&view.Model.PurchasedCount==1&&view.Model.Snapshot.cash==0,"pointer retry installs once and detached repeats cannot overdraw");view.QaClick("menu");At(15);}
   else if(phase==15&&Warm()){Check(UI.Q<Label>("save-status").text.Contains("Saved on this computer"),"successful retry clears English error status");view.QaClick("reset");At(16);}
   else if(phase==16&&Warm()){Check(Focus=="keep-room","safe reset initial focus");int owned=view.Model.PurchasedCount;view.QaClick("keep-room");Check(view.Model.PurchasedCount==owned,"reset cancellation retains room");At(17);}
   else if(phase==17&&Warm()){view.QaClick("reset");At(18);}
   else if(phase==18&&Warm()){view.QaClick("confirm-reset");Check(view.Model.Snapshot.cash==0&&view.Model.Snapshot.freeSpins==3&&view.Model.PurchasedCount==0,"confirmed reset has free starter state");int writes=store.writes;for(int i=0;i<30;i++)Submit(UI.Q<Button>("confirm-reset"));Check(store.writes==writes,"late hidden confirmation remains inert");log.AppendLine("RESULT PASS checks="+checks+"; three actual portrait layouts; real UITK paired navigation/panel pick/pointer/held submit; runtime-clock waits; private profile; no OS input");Finish();}
  }catch(Exception e){log.AppendLine("RESULT FAIL phase="+phase+" "+e);Debug.LogException(e);Finish();}}
  static void Finish(){SessionState.SetBool(Key,false);File.WriteAllText(Path.Combine(Root,"Evidence","v08-compact-input-checks-1.txt"),log.ToString());if(rt!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;rt.Release();UnityEngine.Object.Destroy(rt);}EditorApplication.ExitPlaymode();EditorApplication.delayCall+=()=>EditorApplication.Exit(0);}
 }
}
